"""Save the completed fitting early-clearance research checkpoint."""
from pathlib import Path
from .early_clearance_control import ROOT as EARLY
from .early_contact_diagnosis import ROOT as DIAG
from .conditional_approach_control import ROOT as CONDITIONAL
from .descent_reference_control import ROOT as DESCENT
from .early_exact_diagnostic import ROOT as EXACT
from .abstaining_task_value_gate import read,save

def run():
    for root in (EARLY,CONDITIONAL,DESCENT,EXACT):assert read(root/'status.json')['status']=='complete'
    first=read(EARLY/'summary.json');conditions={**first['variants'],'conditional_high':read(CONDITIONAL/'summary.json'),'descent_cap':read(DESCENT/'summary.json')};eligible=[name for name,v in conditions.items() if v['qualifies']];review=Path('outputs/ease_iteration_review_v1')
    lines=['## Early six-joint contact follow-up (E163–E167)','','The E161 release fix and E120 checkpoints remain unchanged. All192 new six-joint nonprivileged intervention episodes,96 separately labeled privileged diagnostic episodes and16 seven-joint no-op replays are complete; seven-joint results otherwise reuse the unchanged baseline. One extra case12 replay verified an audit-only dtype correction and is not an independent trial. No held test was run.','', '| Six-joint controller | Success /48 | Collision episodes | Rescues / regressions | Fixed screen passed |','|---|---:|---:|---:|---|','| E120 + release baseline | 37 | 11 | — | reference |']
    for name,v in conditions.items():lines.append(f"| {name} | {v['candidate']['6']['success']} | {v['candidate']['6']['collisions']} | {v['gains']} / {v['losses']} | {v['qualifies']} |")
    lines+=['',f'Qualifying variants: {eligible}. The screen requires more successes, fewer first approach/descent contacts, no extra collisions and no lost baseline success. All regressions are retained. No controller or checkpoint is automatically promoted.','', 'The geometry audit is diagnostic only. Contact labels3/4 in older traces are geometry IDs attached to link1/link2, correcting earlier informal link numbering. All11 six-joint baseline collisions occur on body84000. None of the new policies receives geometry distances, body IDs, exact Jacobians, contact signals or future physics. All inactive E165/E166 trajectories match baseline states exactly.','']
    exact=read(EXACT/'summary.json');lines += [f"Privileged exact-current-motion diagnostic: release-only {exact['methods']['release_only']['success']}/48; conditional higher route {exact['methods']['conditional_high']['success']}/48. {exact['gains']} rescues/{exact['losses']} regressions. This replaces the learned controller with an exact-map DLS reference; it is not an E120 or learned-policy result. Residual failures support investigating explicit posture/clearance control, not a claim that feasible paths do not exist.",'']
    p=review/'report.md';text=p.read_text(encoding='utf-8');at=text.index('| Study |');text=text[:at]+'\n'.join(lines)+'\n'+text[at:];additions=[('E163',DIAG,'Offline clearance audit; corrected geometry-ID interpretation.'),('E164',EARLY,'Higher approach and early joint centering; all rescues/regressions retained.'),('E165',CONDITIONAL,'Conditional higher approach using measured8mm lateral-travel threshold.'),('E166',DESCENT,'Conditional higher route plus descent-only30mm position-reference cap.'),('E167',EXACT,'Privileged exact-current-motion matched route diagnostic; no learned-policy claim.')];at=text.index('\n\nInterpretation:');table='\n'.join(f"| {e} | {finding} | [report](../{root.name}/report.md) | "+(f'[videos](../{root.name}/videos/index.html)' if (root/'videos/index.html').exists() else 'Offline audit; source videos linked in report')+' |' for e,root,finding in additions);text=text[:at]+'\n'+table+text[at:];p.write_text(text,encoding='utf-8')
    studies=read(review/'studies.json');assert not any(r['experiment']=='E163' for r in studies);studies += [dict(experiment=e,folder=str(root),report_exists=True,videos=len(list((root/'videos').glob('*.mp4')))) for e,root,_ in additions];save(review/'studies.json',studies)
    summary=dict(new_six_joint_intervention_episodes=192,privileged_diagnostic_episodes=96,seven_joint_exact_replays=16,additional_identical_audit_replay=1,videos=sum(read(root/'status.json')['videos'] for root in (EARLY,CONDITIONAL,DESCENT,EXACT)),conditions=conditions,exact_diagnostic=exact,qualifying_variants=eligible,E120_unchanged=True,release_fix_preserved=True,held_evaluated=False);save(review/'early_contact_summary.json',summary)
    state=review/'WORKING_STATE.md';state.write_text('# Latest checkpoint: E163–E167 complete\n\n'+'\n'.join(lines)+'\nAll jobs and video verification finished. No running experiment remains. E120 and release fix unchanged. E159 was not retested. See early_contact_summary.json and the five reports for complete outcomes.\n\n---\n\n'+state.read_text(encoding='utf-8'),encoding='utf-8');print(summary,flush=True)

if __name__=='__main__':run()
